from abc import ABC, abstractmethod

class Disease:
    def __init__(self, name, transmission, symptoms):
        self.name = name
        self.transmission = transmission
        self.symptoms = symptoms

class TransmissionMethod(ABC):
    def __init__(self, source):
        self.source = source

    @abstractmethod
    def is_asymptomatic(self):
        pass

    def spread(self, disease):
        if disease.symptoms == "asymptomatic" and self.is_asymptomatic():
            return f"The disease is spreading through {self.source} with no symptoms."
        else:
            return f"Disease transmitted through {self.source}."

class FamilyTransmission(TransmissionMethod):
    def is_asymptomatic(self):
        return False

class VectorTransmission(TransmissionMethod):
    def is_asymptomatic(self):
        return False

class CashTransmission(TransmissionMethod):
    def is_asymptomatic(self):
        return False

class WaterborneTransmission(TransmissionMethod):
    def is_asymptomatic(self):
        return False

class DiseaseSpread:
    def __init__(self):
        self.diseases = []

    def add_disease(self, name, transmission, symptoms):
        disease = Disease(name, transmission, symptoms)
        self.diseases.append(disease)

    def spread_diseases(self):
        results = []
        for i, disease in enumerate(self.diseases):
            results.append(disease.source.get_source())
            delay = 2
            for j in range(delay):
                delayed_disease = Disease(name=f"{disease.name} (Variant {j+1})",
                                          transmission=disease.transmission,
                                          symptoms=disease.symptoms)
                delay_key = (f"{delayed_disease.name} (Variant {j+1})",
                             disease.transmission.get_source())
                if delay_key == ("Glioblastoma (Variant 2)", "coughing"):
                    break
                results.append(delay_key)
        return results

