def take_command_and_execute(path, command):
    files = glob.glob(os.path.join(path, '*'))
    for file in files:
        if os.path.isdir(file):
            return
        if os.path.isfile(file):
            if file.endswith('.txt'):
                os.chdir(file)
            else:
                subprocess.call([command, file], shell=True)

def delete_files_command(path):
    command = "rm -rf {}"
    take_command_and_execute(path, command)

