from django.views.generic import TemplateView
from django.urls import reverse
from events.models import Overdose

class OverdoseResponseView(TemplateView):
    template_name = 'calls/overdose.html'

    def get_context_data(self, **kwargs):
        context = super().get_context_data(**kwargs)
        overdose = Overdose.objects.get(id=self.kwargs['id'])
